commits.patch:
diff --git a/lib/parsedate.c b/lib/parsedate.c
index b4dd97b..2bc313b 100644
--- a/lib/parsedate.c
+++ b/lib/parsedate.c
@@ -114,7 +114,8 @@ struct tzinfo {

 #define tDAYZONE (-60)         /* offset for daylight savings time */

-/* alpha-sorted list of single-letter time zones */
+/* alpha-sorted list of single-letter time zones, A - Y. 'Z' (Zulu, zero
+   offset) is handled separately below instead of taking up a table slot. */
 static const struct tzinfo tzone[] = {
   { "A", -1 * 60 },            /* Alpha */
   { "B", -2 * 60 },            /* Bravo */
@@ -141,7 +142,6 @@ static const struct tzinfo tzone[] = {
   { "W", 10 * 60 },            /* Whiskey */
   { "X", 11 * 60 },            /* X-ray */
   { "Y", 12 * 60 },            /* Yankee */
-  { "Z",       0 },            /* Zulu, zero meridian, a.k.a. UTC */
 };

 /* two-letter time zones */
@@ -334,8 +334,11 @@ UNITTEST int checktz(const char *check, size_t len)
   if(len > 4)
     return -1;
   else if(len == 1) {
-    /* short-cut single letter names */
-    if((check[0] < 'A') || (check[0] > 'Z') || (check[0] == 'J'))
+    /* short-cut single letter names. 'Z' (Zulu) is the common case and is
+       handled directly instead of using a table slot for a zero offset. */
+    if(check[0] == 'Z')
+      return 0;
+    if((check[0] < 'A') || (check[0] > 'Y') || (check[0] == 'J'))
       return -1; /* no such tz */
     return tzone[check[0] - 'A'].offset * 60;
   }
